#!/usr/bin/env bash
# ==============================================================================
# guard-protected-paths.sh — PreToolUse hook (ADR 0005, anti-gaming guardrail)
#
# Prevents AI agents from "making the harness green" by editing the harness
# itself or generated artifacts.
#
#   DENY        generated code (must be regenerated by tools, never hand-edited)
#   FORCE_ASK   harness files, accepted ADRs, agent rules (human must approve)
#   ALLOW       everything else (only file-edit tools are routed here)
#
# Modes:
#   (default)   Antigravity hooks.json contract  -> JSON {"decision": ...}
#   --claude    Claude Code hooks contract        -> exit 2 (deny) / JSON ask
# ==============================================================================
set -euo pipefail

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
MODE="${1:-antigravity}"
INPUT="$(cat)"

if [ "$MODE" = "--claude" ]; then
    TARGET=$(jq -r '.tool_input.file_path // .tool_input.path // empty' <<<"$INPUT")
else
    TARGET=$(jq -r '.toolCall.args.TargetFile // .toolCall.args.AbsolutePath // empty' <<<"$INPUT")
fi

REL="${TARGET#"$ROOT_DIR"/}"
DECISION="allow"
REASON=""

case "$REL" in
    src/Frontend/src/shared/api/generated/*|src/Frontend/openapi/*)
        DECISION="deny"
        REASON="'$REL' is generated (ADR 0007). Change the C# endpoint/DTO and run 'npm run codegen:api' instead of editing it." ;;
    */Migrations/*.cs)
        DECISION="deny"
        REASON="'$REL' is an EF Core migration. Generate migrations with 'dotnet ef migrations add <Name>'; never hand-edit them." ;;
    tests/Architecture.Tests/*|scripts/*|.githooks/*|.github/*|.agents/hooks.json|.claude/settings.json|AGENTS.md|CLAUDE.md|*/AGENTS.md)
        DECISION="force_ask"
        REASON="'$REL' is part of the architecture harness. Changing it requires explicit human approval. If a guardrail blocks you, fix the code, not the guardrail." ;;
    docs/adr/[0-9][0-9][0-9][0-9]-*.md)
        if [ -f "$TARGET" ] && grep -qE '^(Accepted|Superseded by)' "$TARGET"; then
            DECISION="force_ask"
            REASON="'$REL' is an accepted ADR and is immutable. Draft a new ADR with 'scripts/new-adr.sh' that supersedes or amends it."
        fi ;;
esac

if [ "$MODE" = "--claude" ]; then
    case "$DECISION" in
        deny) echo "$REASON" >&2; exit 2 ;;
        force_ask)
            jq -n --arg r "$REASON" '{hookSpecificOutput: {hookEventName: "PreToolUse", permissionDecision: "ask", permissionDecisionReason: $r}}'
            exit 0 ;;
        *) exit 0 ;;
    esac
fi

if [ -n "$REASON" ]; then
    jq -n --arg d "$DECISION" --arg r "$REASON" '{decision: $d, reason: $r}'
else
    jq -n '{decision: "allow"}'
fi
